import * as React from "react"

import { InputGroup, InputGroupInput } from "@/components/ui/input-group"
import { cn } from "@/lib/utils"
import { onlyDigits, type CardBrand } from "./lib"

export type CardCvcInputProps = Omit<
  React.ComponentProps<"input">,
  "value" | "defaultValue" | "onChange" | "type" | "inputMode"
> & {
  value?: string
  defaultValue?: string
  onValueChange?: (digits: string) => void
  /** Amex uses 4 digits; others 3. */
  brand?: CardBrand
  invalid?: boolean
}

function CardCvcInput({
  value: valueProp,
  defaultValue = "",
  onValueChange,
  brand = "unknown",
  invalid,
  className,
  disabled,
  id,
  ...props
}: CardCvcInputProps) {
  const maxLen = brand === "amex" ? 4 : 3
  const [uncontrolled, setUncontrolled] = React.useState(() =>
    onlyDigits(defaultValue).slice(0, maxLen)
  )
  const isControlled = valueProp !== undefined
  const digits = onlyDigits(isControlled ? (valueProp ?? "") : uncontrolled).slice(
    0,
    maxLen
  )

  const showInvalid = invalid ?? false

  const setDigits = (next: string) => {
    const clipped = onlyDigits(next).slice(0, maxLen)
    if (!isControlled) setUncontrolled(clipped)
    onValueChange?.(clipped)
  }

  return (
    <InputGroup
      className={cn(
        showInvalid &&
          "has-[[data-slot=input-group-control]]:border-destructive",
        className
      )}
      data-disabled={disabled ? "" : undefined}
      data-invalid={showInvalid ? "" : undefined}
    >
      <InputGroupInput
        id={id}
        type="text"
        inputMode="numeric"
        autoComplete="cc-csc"
        placeholder={brand === "amex" ? "1234" : "123"}
        maxLength={maxLen}
        disabled={disabled}
        value={digits}
        aria-invalid={showInvalid || undefined}
        data-slot="input-group-control"
        className="tabular-nums"
        onChange={(e) => setDigits(e.target.value)}
        {...props}
      />
    </InputGroup>
  )
}

export { CardCvcInput }

"use client"

import * as React from "react"

import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
  InputGroupText,
} from "@/components/ui/input-group"
import { cn } from "@/lib/utils"
import {
  caretFromAlnumCount,
  countAlnumBefore,
  formatIban,
  isValidIban,
  sanitizeIban,
} from "./lib"

export type IbanInputProps = Omit<
  React.ComponentProps<"input">,
  "value" | "defaultValue" | "onChange" | "type"
> & {
  /** Raw IBAN without spaces (controlled). */
  value?: string
  defaultValue?: string
  onValueChange?: (iban: string) => void
  /** Show country code from first 2 letters. */
  showCountry?: boolean
  invalid?: boolean
}

function IbanInput({
  value: valueProp,
  defaultValue = "",
  onValueChange,
  showCountry = true,
  invalid,
  className,
  disabled,
  id,
  onBlur,
  onFocus,
  ...props
}: IbanInputProps) {
  const [uncontrolled, setUncontrolled] = React.useState(() =>
    sanitizeIban(defaultValue)
  )
  const isControlled = valueProp !== undefined
  const raw = sanitizeIban(isControlled ? (valueProp ?? "") : uncontrolled).slice(
    0,
    34
  )
  const display = formatIban(raw)
  const country = raw.slice(0, 2)
  const [focused, setFocused] = React.useState(false)
  const inputRef = React.useRef<HTMLInputElement>(null)

  const valid = isValidIban(raw)
  const showInvalid =
    invalid ?? (raw.length >= 15 && !valid && !focused)

  const setRaw = (next: string) => {
    const clipped = sanitizeIban(next).slice(0, 34)
    if (!isControlled) setUncontrolled(clipped)
    onValueChange?.(clipped)
  }

  return (
    <InputGroup
      className={cn(
        showInvalid &&
          "has-[[data-slot=input-group-control]]:border-destructive",
        className
      )}
      data-disabled={disabled ? "" : undefined}
      data-invalid={showInvalid ? "" : undefined}
      data-valid={valid ? "" : undefined}
    >
      {showCountry && /^[A-Z]{2}/.test(country) ? (
        <InputGroupAddon align="inline-start">
          <InputGroupText className="text-xs font-medium uppercase">
            {country}
          </InputGroupText>
        </InputGroupAddon>
      ) : null}
      <InputGroupInput
        ref={inputRef}
        id={id}
        type="text"
        autoComplete="off"
        spellCheck={false}
        disabled={disabled}
        value={display}
        placeholder="DE89 3704 0044 0532 0130 00"
        aria-invalid={showInvalid || undefined}
        data-slot="input-group-control"
        className="font-mono text-sm uppercase tracking-wide"
        onFocus={(e) => {
          setFocused(true)
          onFocus?.(e)
        }}
        onBlur={(e) => {
          setFocused(false)
          onBlur?.(e)
        }}
        onChange={(e) => {
          const el = e.target
          const caret = el.selectionStart ?? el.value.length
          const alnumCount = countAlnumBefore(el.value, caret)
          const next = sanitizeIban(el.value).slice(0, 34)
          setRaw(next)
          const formatted = formatIban(next)
          requestAnimationFrame(() => {
            const node = inputRef.current
            if (!node) return
            const pos = caretFromAlnumCount(formatted, alnumCount)
            node.setSelectionRange(pos, pos)
          })
        }}
        {...props}
      />
    </InputGroup>
  )
}

export { IbanInput }

export type CardBrand =
  | "visa"
  | "mastercard"
  | "amex"
  | "discover"
  | "diners"
  | "jcb"
  | "unionpay"
  | "unknown"

export function onlyDigits(value: string): string {
  return value.replace(/\D/g, "")
}

export function luhnCheck(digits: string): boolean {
  if (digits.length < 12) return false
  let sum = 0
  let alt = false
  for (let i = digits.length - 1; i >= 0; i--) {
    let n = Number(digits[i])
    if (Number.isNaN(n)) return false
    if (alt) {
      n *= 2
      if (n > 9) n -= 9
    }
    sum += n
    alt = !alt
  }
  return sum % 10 === 0
}

export function detectCardBrand(digits: string): CardBrand {
  const d = onlyDigits(digits)
  if (/^4/.test(d)) return "visa"
  if (/^(5[1-5]|2[2-7])/.test(d)) return "mastercard"
  if (/^3[47]/.test(d)) return "amex"
  if (/^6(?:011|5)/.test(d)) return "discover"
  if (/^3(?:0[0-5]|[68])/.test(d)) return "diners"
  if (/^35/.test(d)) return "jcb"
  if (/^62/.test(d)) return "unionpay"
  return "unknown"
}

export function cardBrandLabel(brand: CardBrand): string {
  switch (brand) {
    case "visa":
      return "Visa"
    case "mastercard":
      return "Mastercard"
    case "amex":
      return "Amex"
    case "discover":
      return "Discover"
    case "diners":
      return "Diners"
    case "jcb":
      return "JCB"
    case "unionpay":
      return "UnionPay"
    default:
      return "Card"
  }
}

/** Max digits for the brand (Amex 15, Diners 14, else 16–19). */
export function cardMaxLength(brand: CardBrand): number {
  if (brand === "amex") return 15
  if (brand === "diners") return 14
  return 19
}

/** Group pattern for display. */
export function formatCardNumber(digits: string, brand?: CardBrand): string {
  const d = onlyDigits(digits)
  const b = brand ?? detectCardBrand(d)
  if (b === "amex") {
    const p1 = d.slice(0, 4)
    const p2 = d.slice(4, 10)
    const p3 = d.slice(10, 15)
    return [p1, p2, p3].filter(Boolean).join(" ")
  }
  if (b === "diners") {
    const p1 = d.slice(0, 4)
    const p2 = d.slice(4, 10)
    const p3 = d.slice(10, 14)
    return [p1, p2, p3].filter(Boolean).join(" ")
  }
  return d.replace(/(\d{4})(?=\d)/g, "$1 ").trim()
}

export function maskCardNumber(digits: string, brand?: CardBrand): string {
  const d = onlyDigits(digits)
  if (d.length <= 4) return formatCardNumber(d, brand)
  const maskedDigits = `${"*".repeat(Math.max(0, d.length - 4))}${d.slice(-4)}`
  const b = brand ?? detectCardBrand(d)
  // formatCardNumber strips non-digits - group the masked string manually.
  if (b === "amex") {
    return [maskedDigits.slice(0, 4), maskedDigits.slice(4, 10), maskedDigits.slice(10, 15)]
      .filter(Boolean)
      .join(" ")
  }
  if (b === "diners") {
    return [maskedDigits.slice(0, 4), maskedDigits.slice(4, 10), maskedDigits.slice(10, 14)]
      .filter(Boolean)
      .join(" ")
  }
  return maskedDigits.replace(/(.{4})(?=.)/g, "$1 ").trim()
}

export function isCardNumberComplete(digits: string): boolean {
  const d = onlyDigits(digits)
  const brand = detectCardBrand(d)
  const min = brand === "amex" ? 15 : brand === "diners" ? 14 : 16
  return d.length >= min && luhnCheck(d)
}

export function formatCardExpiry(digits: string): string {
  const d = onlyDigits(digits).slice(0, 4)
  if (d.length <= 2) return d
  return `${d.slice(0, 2)}/${d.slice(2)}`
}

export function parseCardExpiry(formatted: string): {
  month: string
  year: string
  valid: boolean
} {
  const d = onlyDigits(formatted).slice(0, 4)
  const month = d.slice(0, 2)
  const year = d.slice(2, 4)
  if (d.length < 4) return { month, year, valid: false }
  const m = Number(month)
  if (m < 1 || m > 12) return { month, year, valid: false }
  const now = new Date()
  const yy = now.getFullYear() % 100
  const mm = now.getMonth() + 1
  const y = Number(year)
  const valid = y > yy || (y === yy && m >= mm)
  return { month, year, valid }
}

export function formatIban(raw: string): string {
  const cleaned = raw.replace(/[^a-zA-Z0-9]/g, "").toUpperCase()
  return cleaned.replace(/(.{4})(?=.)/g, "$1 ").trim()
}

export function sanitizeIban(raw: string): string {
  return raw.replace(/[^a-zA-Z0-9]/g, "").toUpperCase()
}

/** ISO 13616 mod-97 check. */
export function isValidIban(raw: string): boolean {
  const iban = sanitizeIban(raw)
  if (iban.length < 15 || iban.length > 34) return false
  if (!/^[A-Z]{2}\d{2}[A-Z0-9]+$/.test(iban)) return false
  const rearranged = iban.slice(4) + iban.slice(0, 4)
  let expanded = ""
  for (const ch of rearranged) {
    const code = ch.charCodeAt(0)
    if (code >= 65 && code <= 90) expanded += String(code - 55)
    else expanded += ch
  }
  // Chunked mod 97 for big integers
  let rest = 0
  for (let i = 0; i < expanded.length; i += 7) {
    const block = String(rest) + expanded.slice(i, i + 7)
    rest = Number(block) % 97
  }
  return rest === 1
}

export function countDigitsBefore(text: string, caret: number): number {
  const slice = text.slice(0, Math.max(0, caret))
  return (slice.match(/\d/g) ?? []).length
}

export function caretFromDigitCount(formatted: string, digitCount: number): number {
  if (digitCount <= 0) return 0
  let seen = 0
  for (let i = 0; i < formatted.length; i++) {
    if (/\d/.test(formatted[i]!)) {
      seen++
      if (seen >= digitCount) return i + 1
    }
  }
  return formatted.length
}

export function countAlnumBefore(text: string, caret: number): number {
  const slice = text.slice(0, Math.max(0, caret)).replace(/[^a-zA-Z0-9]/gi, "")
  return slice.length
}

export function caretFromAlnumCount(formatted: string, count: number): number {
  if (count <= 0) return 0
  let seen = 0
  for (let i = 0; i < formatted.length; i++) {
    if (/[a-zA-Z0-9]/i.test(formatted[i]!)) {
      seen++
      if (seen >= count) return i + 1
    }
  }
  return formatted.length
}
